import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Reef: Performance","description":"","frontmatter":{"title":"CDS Reef: Performance","date":"2022-04-14T00:00:00.000Z","updated":"2022-04-15T00:00:00.000Z","tags":["Ceph","RocksDB","AVL分配器","PG日志","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/CDS_Reef_-_Performance.md","filePath":"posts/2022/CDS_Reef_-_Performance.md","lastUpdated":1780459816000}'),a={name:"posts/2022/CDS_Reef_-_Performance.md"};function l(n,e,i,c,P,_){return t(),r("div",null,[...e[0]||(e[0]=[s('<p>在本次CDS Reef性能会议中，主要讨论了以下几个关键议题：</p><h3 id="新pull-requests-prs" tabindex="-1">新Pull Requests (PRs) <a class="header-anchor" href="#新pull-requests-prs" aria-label="Permalink to &quot;新Pull Requests (PRs)&quot;">​</a></h3><ol><li><strong>Corey的PR</strong>：涉及在RocksDB omap迭代器中设置上下限，Casey正在审查并提出了避免拷贝和内存泄漏的建议。</li><li><strong>RGW使用DEOS作为后端存储的PR</strong>：DEOS是一个基于Luster的高性能对象存储系统，目前还处于实验阶段。</li><li><strong>AVL分配器的修复PR</strong>：解决了之前改变导致的分配问题。</li><li><strong>AVL分配器的早期修复PR</strong>：已被新的PR取代。</li><li><strong>AVL分配器基于时间的搜索阈值PR</strong>：改变AVL分配器以基于时间阈值进行搜索，而不是当前的字节和循环计数。</li><li><strong>跟踪更新PR</strong>：Typica进行了审查。</li></ol><h3 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h3><ol><li><strong>AVL分配器性能</strong>：讨论了AVL分配器的搜索策略，特别是从近似匹配模式切换到最佳匹配模式的阈值设置。</li><li><strong>PG日志优化</strong>：讨论了PG日志的写入和存储问题，特别是与RocksDB的集成和性能影响。</li></ol><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ol><li><strong>AVL分配器</strong>：决定继续探索基于时间的搜索限制，并可能支持两种限制方式以确保其有效性。</li><li><strong>PG日志</strong>：决定进一步研究和原型化使用RocksDB的写前日志机制来优化PG日志的存储和管理。</li></ol><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ol><li><strong>AVL分配器</strong>：继续测试和验证基于时间的搜索限制。</li><li><strong>PG日志</strong>：原型化并测试使用RocksDB的写前日志机制来优化PG日志的存储和管理。</li><li><strong>会议安排</strong>：下一次会议将首先讨论Corey关于RocksDB迭代器边界的工作，然后继续PG日志的讨论。</li></ol><p>此次会议还涉及了其他一些技术细节和潜在的性能优化点，包括对RocksDB写前日志的深入讨论和可能的改进。</p>',10)])])}const p=o(a,[["render",l]]);export{g as __pageData,p as default};
